-- fraud_score: Immutable fraud evaluation of one event (authorisation, payment, login, ...) with decision and reasons
CREATE TABLE fraud_score (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  subject_type                 varchar(40) NOT NULL CHECK (subject_type IN ('CARD_AUTHORIZATION', 'PAYMENT', 'WALLET_TRANSACTION', 'LOGIN', 'ONBOARDING', 'BENEFICIARY_CHANGE', 'DEVICE_CHANGE', 'PROFILE_CHANGE', 'LOAN_APPLICATION')),
  subject_id                   uuid NOT NULL,
  customer_id                  uuid,
  account_id                   uuid,
  card_id                      uuid,
  amount                       numeric(28,8),
  currency                     char(3),
  channel                      varchar(40) CHECK (channel IN ('MOBILE_APP', 'WEB', 'API', 'USSD', 'AGENT', 'BRANCH', 'POS', 'ATM', 'ECOMMERCE', 'CONTACTLESS', 'OPEN_BANKING')),
  merchant_category_code       varchar(4),
  counterparty_country         char(2),
  device_fingerprint_id        uuid REFERENCES device_fingerprint(id),
  ip_address                   inet,
  score                        integer NOT NULL,
  model_score                  integer,
  rule_score                   integer,
  model_id                     uuid,
  model_version                varchar(32),
  decision                     varchar(40) NOT NULL CHECK (decision IN ('ALLOW', 'REVIEW', 'BLOCK', 'STEP_UP')),
  reason_codes                 jsonb NOT NULL,
  features                     jsonb,
  shadow_decision              varchar(40) CHECK (shadow_decision IN ('ALLOW', 'REVIEW', 'BLOCK', 'STEP_UP')),
  latency_ms                   integer NOT NULL,
  correlation_id               varchar(128),
  session_id                   varchar(128),
  fraud_alert_id               uuid,
  idempotency_key              varchar(128),
  rules_component_score        integer,
  combination                  varchar(40) CHECK (combination IN ('ADDITIVE', 'MAX', 'WEIGHTED', 'MODEL_ONLY_ABOVE_CONFIDENCE', 'RULES_ONLY')),
  ml_model_version_id          uuid,
  ml_deployment_id             uuid,
  degraded                     boolean NOT NULL DEFAULT false,
  degraded_reason              varchar(64),
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_fraud_score_1 UNIQUE (tenant_id, idempotency_key)
);
COMMENT ON TABLE fraud_score IS 'Immutable fraud evaluation of one event (authorisation, payment, login, ...) with decision and reasons';
COMMENT ON COLUMN fraud_score.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN fraud_score.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN fraud_score.created_at IS 'Creation time';
COMMENT ON COLUMN fraud_score.created_by IS 'Principal that created the row';
COMMENT ON COLUMN fraud_score.subject_type IS 'Kind of event scored';
COMMENT ON COLUMN fraud_score.subject_id IS 'Id of the event in its service (payment, authorisation, ...)';
COMMENT ON COLUMN fraud_score.customer_id IS 'Customer';
COMMENT ON COLUMN fraud_score.account_id IS 'Account debited, if any';
COMMENT ON COLUMN fraud_score.card_id IS 'Card, for card events';
COMMENT ON COLUMN fraud_score.amount IS 'Transaction amount';
COMMENT ON COLUMN fraud_score.currency IS 'Transaction currency';
COMMENT ON COLUMN fraud_score.channel IS 'Channel the event came from';
COMMENT ON COLUMN fraud_score.merchant_category_code IS 'MCC, for card events';
COMMENT ON COLUMN fraud_score.counterparty_country IS 'Counterparty or merchant country';
COMMENT ON COLUMN fraud_score.device_fingerprint_id IS 'Device used';
COMMENT ON COLUMN fraud_score.ip_address IS 'Client IP address';
COMMENT ON COLUMN fraud_score.score IS 'Final risk score 0-1000 (higher = riskier)';
COMMENT ON COLUMN fraud_score.model_score IS 'Raw ML model score 0-1000';
COMMENT ON COLUMN fraud_score.rule_score IS 'Net score adjustment from rules';
COMMENT ON COLUMN fraud_score.model_id IS 'Model used';
COMMENT ON COLUMN fraud_score.model_version IS 'Model version used';
COMMENT ON COLUMN fraud_score.decision IS 'Decision returned to the caller';
COMMENT ON COLUMN fraud_score.reason_codes IS 'Ordered reason codes explaining the decision';
COMMENT ON COLUMN fraud_score.features IS 'Feature values used (for audit, explainability and rule backtesting)';
COMMENT ON COLUMN fraud_score.shadow_decision IS 'Decision of the shadow / challenger model';
COMMENT ON COLUMN fraud_score.latency_ms IS 'Evaluation time in milliseconds';
COMMENT ON COLUMN fraud_score.correlation_id IS 'Trace / saga correlation id';
COMMENT ON COLUMN fraud_score.session_id IS 'App session (links behavioural signals)';
COMMENT ON COLUMN fraud_score.fraud_alert_id IS 'Alert raised for REVIEW / BLOCK decisions';
COMMENT ON COLUMN fraud_score.idempotency_key IS 'Client key; a replay returns the original evaluation';
COMMENT ON COLUMN fraud_score.rules_component_score IS 'Rule-based score (built-in heuristic model + rule adjustments) before it is combined with the ML score';
COMMENT ON COLUMN fraud_score.combination IS 'How the rule-based and ML scores were combined (empty = no ML model in the policy)';
COMMENT ON COLUMN fraud_score.ml_model_version_id IS 'ML model version (ai-platform) that decided';
COMMENT ON COLUMN fraud_score.ml_deployment_id IS 'ai-platform deployment (champion or canary) that decided';
COMMENT ON COLUMN fraud_score.degraded IS 'The ML model was unavailable, failed or exceeded its budget; rules decided';
COMMENT ON COLUMN fraud_score.degraded_reason IS 'MODEL_UNAVAILABLE, NO_CHAMPION, CHECKSUM_MISMATCH, INVALID_ARTIFACT, MODEL_ERROR, MODEL_TIMEOUT, FEATURES_UNAVAILABLE';
COMMENT ON COLUMN fraud_score.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN fraud_score.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN fraud_score.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN fraud_score.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN fraud_score.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_fraud_score_tenant ON fraud_score (tenant_id, created_at);
CREATE INDEX ix_fraud_score_subject_id ON fraud_score (subject_id);
CREATE INDEX ix_fraud_score_customer_id ON fraud_score (customer_id);
CREATE INDEX ix_fraud_score_account_id ON fraud_score (account_id);
CREATE INDEX ix_fraud_score_card_id ON fraud_score (card_id);
CREATE INDEX ix_fraud_score_device_fingerprint_id ON fraud_score (device_fingerprint_id);
CREATE INDEX ix_fraud_score_model_id ON fraud_score (model_id);
CREATE INDEX ix_fraud_score_correlation_id ON fraud_score (correlation_id);
CREATE INDEX ix_fraud_score_ml_model_version_id ON fraud_score (ml_model_version_id);
CREATE INDEX ix_fraud_score_ml_deployment_id ON fraud_score (ml_deployment_id);
CREATE INDEX ix_fraud_score_c1 ON fraud_score (subject_type, subject_id);
CREATE INDEX ix_fraud_score_c2 ON fraud_score (customer_id, created_at);
CREATE INDEX ix_fraud_score_c3 ON fraud_score (device_fingerprint_id, created_at);
ALTER TABLE fraud_score ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON fraud_score USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_fraud_score_append_only BEFORE UPDATE OR DELETE ON fraud_score FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

-- fraud_rule_hit: A rule that fired during one fraud evaluation. Append-only.
CREATE TABLE fraud_rule_hit (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  fraud_score_id               uuid NOT NULL REFERENCES fraud_score(id),
  fraud_rule_id                uuid NOT NULL REFERENCES fraud_rule(id),
  rule_version                 integer NOT NULL,
  action                       varchar(40) NOT NULL CHECK (action IN ('ALLOW', 'REVIEW', 'BLOCK', 'STEP_UP', 'SCORE_ADJUST', 'TAG')),
  score_adjustment             integer NOT NULL DEFAULT 0,
  shadow                       boolean NOT NULL DEFAULT false,
  matched_values               jsonb,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE fraud_rule_hit IS 'A rule that fired during one fraud evaluation. Append-only.';
COMMENT ON COLUMN fraud_rule_hit.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN fraud_rule_hit.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN fraud_rule_hit.created_at IS 'Creation time';
COMMENT ON COLUMN fraud_rule_hit.created_by IS 'Principal that created the row';
COMMENT ON COLUMN fraud_rule_hit.fraud_score_id IS 'Evaluation';
COMMENT ON COLUMN fraud_rule_hit.fraud_rule_id IS 'Rule';
COMMENT ON COLUMN fraud_rule_hit.rule_version IS 'Rule version evaluated';
COMMENT ON COLUMN fraud_rule_hit.action IS 'Action taken';
COMMENT ON COLUMN fraud_rule_hit.score_adjustment IS 'Points applied';
COMMENT ON COLUMN fraud_rule_hit.shadow IS 'Rule was in shadow mode';
COMMENT ON COLUMN fraud_rule_hit.matched_values IS 'Values of the identifiers the expression referenced';
