-- fraud_alert: A suspicious event queued for analyst review
CREATE TABLE fraud_alert (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  fraud_score_id               uuid REFERENCES fraud_score(id),
  customer_id                  uuid,
  subject_type                 varchar(40) NOT NULL CHECK (subject_type IN ('CARD_AUTHORIZATION', 'PAYMENT', 'WALLET_TRANSACTION', 'LOGIN', 'ONBOARDING', 'BENEFICIARY_CHANGE', 'DEVICE_CHANGE', 'PROFILE_CHANGE', 'LOAN_APPLICATION')),
  subject_id                   uuid NOT NULL,
  severity                     varchar(40) NOT NULL CHECK (severity IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
  status                       varchar(40) NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN', 'IN_REVIEW', 'CONFIRMED_FRAUD', 'FALSE_POSITIVE', 'ESCALATED', 'CLOSED')),
  reason_codes                 jsonb,
  typology                     varchar(40) CHECK (typology IN ('ACCOUNT_TAKEOVER', 'CARD_NOT_PRESENT', 'CARD_PRESENT_COUNTERFEIT', 'AUTHORISED_PUSH_PAYMENT_SCAM', 'FIRST_PARTY', 'SYNTHETIC_IDENTITY', 'MONEY_MULE', 'FRIENDLY_FRAUD', 'SIM_SWAP', 'INSIDER', 'OTHER')),
  amount                       numeric(28,8),
  currency                     char(3),
  assigned_to                  varchar(64),
  sla_due_at                   timestamptz,
  customer_contacted           boolean NOT NULL DEFAULT false,
  notification_id              uuid,
  resolution                   text,
  resolved_by                  varchar(64),
  resolved_at                  timestamptz,
  aml_case_id                  uuid,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE fraud_alert IS 'A suspicious event queued for analyst review';
COMMENT ON COLUMN fraud_alert.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN fraud_alert.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN fraud_alert.created_at IS 'Creation time';
COMMENT ON COLUMN fraud_alert.created_by IS 'Principal that created the row';
COMMENT ON COLUMN fraud_alert.updated_at IS 'Last update time';
COMMENT ON COLUMN fraud_alert.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN fraud_alert.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN fraud_alert.fraud_score_id IS 'Evaluation that raised the alert';
COMMENT ON COLUMN fraud_alert.customer_id IS 'Customer';
COMMENT ON COLUMN fraud_alert.subject_type IS 'Event type';
COMMENT ON COLUMN fraud_alert.subject_id IS 'Event id';
COMMENT ON COLUMN fraud_alert.severity IS 'Severity';
COMMENT ON COLUMN fraud_alert.status IS 'Status (changed only by actions)';
COMMENT ON COLUMN fraud_alert.reason_codes IS 'Reason codes of the evaluation that raised the alert';
COMMENT ON COLUMN fraud_alert.typology IS 'Suspected or confirmed typology';
COMMENT ON COLUMN fraud_alert.amount IS 'Amount at risk';
COMMENT ON COLUMN fraud_alert.currency IS 'Currency';
COMMENT ON COLUMN fraud_alert.assigned_to IS 'Analyst';
COMMENT ON COLUMN fraud_alert.sla_due_at IS 'Review deadline';
COMMENT ON COLUMN fraud_alert.customer_contacted IS 'Customer confirm-or-deny message sent';
COMMENT ON COLUMN fraud_alert.notification_id IS 'Confirm-or-deny notification';
COMMENT ON COLUMN fraud_alert.resolution IS 'Resolution notes';
COMMENT ON COLUMN fraud_alert.resolved_by IS 'Analyst who resolved';
COMMENT ON COLUMN fraud_alert.resolved_at IS 'Resolution time';
COMMENT ON COLUMN fraud_alert.aml_case_id IS 'Case opened from this alert';
COMMENT ON COLUMN fraud_alert.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN fraud_alert.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN fraud_alert.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN fraud_alert.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN fraud_alert.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_fraud_alert_tenant ON fraud_alert (tenant_id, created_at);
CREATE INDEX ix_fraud_alert_fraud_score_id ON fraud_alert (fraud_score_id);
CREATE INDEX ix_fraud_alert_customer_id ON fraud_alert (customer_id);
CREATE INDEX ix_fraud_alert_assigned_to ON fraud_alert (assigned_to);
CREATE INDEX ix_fraud_alert_notification_id ON fraud_alert (notification_id);
CREATE INDEX ix_fraud_alert_aml_case_id ON fraud_alert (aml_case_id);
ALTER TABLE fraud_alert ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON fraud_alert USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_fraud_alert_touch BEFORE UPDATE ON fraud_alert FOR EACH ROW EXECUTE FUNCTION touch_row();

-- fraud_feedback: Confirmed outcome label for a scored event, used for model training and rule tuning
CREATE TABLE fraud_feedback (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  fraud_score_id               uuid NOT NULL REFERENCES fraud_score(id),
  label                        varchar(40) NOT NULL CHECK (label IN ('FRAUD', 'NOT_FRAUD', 'UNKNOWN')),
  typology                     varchar(40) CHECK (typology IN ('ACCOUNT_TAKEOVER', 'CARD_NOT_PRESENT', 'CARD_PRESENT_COUNTERFEIT', 'AUTHORISED_PUSH_PAYMENT_SCAM', 'FIRST_PARTY', 'SYNTHETIC_IDENTITY', 'MONEY_MULE', 'FRIENDLY_FRAUD', 'SIM_SWAP', 'INSIDER', 'OTHER')),
  source                       varchar(32) NOT NULL,
  loss_amount                  numeric(28,8),
  currency                     char(3),
  recovered_amount             numeric(28,8),
  reported_at                  timestamptz NOT NULL,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE fraud_feedback IS 'Confirmed outcome label for a scored event, used for model training and rule tuning';
COMMENT ON COLUMN fraud_feedback.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN fraud_feedback.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN fraud_feedback.created_at IS 'Creation time';
COMMENT ON COLUMN fraud_feedback.created_by IS 'Principal that created the row';
COMMENT ON COLUMN fraud_feedback.fraud_score_id IS 'Evaluation being labelled';
COMMENT ON COLUMN fraud_feedback.label IS 'Outcome';
COMMENT ON COLUMN fraud_feedback.typology IS 'Fraud typology';
COMMENT ON COLUMN fraud_feedback.source IS 'ANALYST, CHARGEBACK, CUSTOMER_REPORT, CONSORTIUM';
COMMENT ON COLUMN fraud_feedback.loss_amount IS 'Loss incurred';
COMMENT ON COLUMN fraud_feedback.currency IS 'Currency';
COMMENT ON COLUMN fraud_feedback.recovered_amount IS 'Amount recovered';
COMMENT ON COLUMN fraud_feedback.reported_at IS 'When the outcome became known';
COMMENT ON COLUMN fraud_feedback.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN fraud_feedback.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN fraud_feedback.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN fraud_feedback.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN fraud_feedback.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_fraud_feedback_tenant ON fraud_feedback (tenant_id, created_at);
CREATE INDEX ix_fraud_feedback_fraud_score_id ON fraud_feedback (fraud_score_id);
ALTER TABLE fraud_feedback ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON fraud_feedback USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_fraud_feedback_append_only BEFORE UPDATE OR DELETE ON fraud_feedback FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

-- fraud_model_score: Score of one ML model deployment for one evaluation (champion, canary, challenger or shadow). Append-only; feeds monitoring
CREATE TABLE fraud_model_score (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  fraud_score_id               uuid NOT NULL REFERENCES fraud_score(id),
  subject_type                 varchar(40) NOT NULL CHECK (subject_type IN ('CARD_AUTHORIZATION', 'PAYMENT', 'WALLET_TRANSACTION', 'LOGIN', 'ONBOARDING', 'BENEFICIARY_CHANGE', 'DEVICE_CHANGE', 'PROFILE_CHANGE', 'LOAN_APPLICATION')),
  channel                      varchar(40) CHECK (channel IN ('MOBILE_APP', 'WEB', 'API', 'USSD', 'AGENT', 'BRANCH', 'POS', 'ATM', 'ECOMMERCE', 'CONTACTLESS', 'OPEN_BANKING')),
  ml_model_id                  uuid NOT NULL,
  ml_model_version_id          uuid NOT NULL,
  model_deployment_id          uuid,
  model_version                varchar(32),
  role                         varchar(40) NOT NULL CHECK (role IN ('CHAMPION', 'CANARY', 'CHALLENGER', 'SHADOW')),
  decided                      boolean NOT NULL DEFAULT false,
  score                        integer,
  probability                  numeric(18,10),
  would_decide                 varchar(40) CHECK (would_decide IN ('ALLOW', 'REVIEW', 'BLOCK', 'STEP_UP')),
  latency_us                   integer NOT NULL DEFAULT 0,
  error                        varchar(255),
  feature_vector               jsonb,
  top_contributions            jsonb,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE fraud_model_score IS 'Score of one ML model deployment for one evaluation (champion, canary, challenger or shadow). Append-only; feeds monitoring';
COMMENT ON COLUMN fraud_model_score.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN fraud_model_score.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN fraud_model_score.created_at IS 'Creation time';
COMMENT ON COLUMN fraud_model_score.created_by IS 'Principal that created the row';
COMMENT ON COLUMN fraud_model_score.fraud_score_id IS 'Evaluation';
COMMENT ON COLUMN fraud_model_score.subject_type IS 'Event type';
COMMENT ON COLUMN fraud_model_score.channel IS 'Channel';
COMMENT ON COLUMN fraud_model_score.ml_model_id IS 'ai-platform model';
COMMENT ON COLUMN fraud_model_score.ml_model_version_id IS 'ai-platform model version';
COMMENT ON COLUMN fraud_model_score.model_deployment_id IS 'ai-platform deployment';
COMMENT ON COLUMN fraud_model_score.model_version IS 'Version label';
COMMENT ON COLUMN fraud_model_score.role IS 'Role of the deployment for this evaluation';
COMMENT ON COLUMN fraud_model_score.decided IS 'This score decided (champion or canary slice); challengers and shadows never decide';
COMMENT ON COLUMN fraud_model_score.score IS 'Score 0-1000 (empty on error)';
COMMENT ON COLUMN fraud_model_score.probability IS 'Fraud probability';
COMMENT ON COLUMN fraud_model_score.would_decide IS 'Decision this score alone would have produced';
COMMENT ON COLUMN fraud_model_score.latency_us IS 'Inference time in microseconds';
COMMENT ON COLUMN fraud_model_score.error IS 'Why the model produced no score';
COMMENT ON COLUMN fraud_model_score.feature_vector IS 'Model inputs (for drift monitoring and retraining)';
COMMENT ON COLUMN fraud_model_score.top_contributions IS 'Largest feature contributions {feature, value, contribution}';
COMMENT ON COLUMN fraud_model_score.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN fraud_model_score.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN fraud_model_score.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN fraud_model_score.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN fraud_model_score.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_fraud_model_score_tenant ON fraud_model_score (tenant_id, created_at);
CREATE INDEX ix_fraud_model_score_fraud_score_id ON fraud_model_score (fraud_score_id);
CREATE INDEX ix_fraud_model_score_ml_model_id ON fraud_model_score (ml_model_id);
CREATE INDEX ix_fraud_model_score_ml_model_version_id ON fraud_model_score (ml_model_version_id);
CREATE INDEX ix_fraud_model_score_model_deployment_id ON fraud_model_score (model_deployment_id);
CREATE INDEX ix_fraud_model_score_c1 ON fraud_model_score (model_deployment_id, created_at);
CREATE INDEX ix_fraud_model_score_c2 ON fraud_model_score (ml_model_id, created_at);
ALTER TABLE fraud_model_score ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON fraud_model_score USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_fraud_model_score_append_only BEFORE UPDATE OR DELETE ON fraud_model_score FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

-- Transactional outbox: events are written here in the same transaction as the
-- state change and relayed to Kafka by the outbox relay (Debezium).
CREATE TABLE outbox (
  id              uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id       uuid NOT NULL,
  aggregate_type  varchar(64) NOT NULL,
  aggregate_id    uuid NOT NULL,
  event_type      varchar(128) NOT NULL,
  payload         jsonb NOT NULL,
  headers         jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_outbox_created ON outbox (created_at);

-- Idempotency keys for POST requests (24h retention).
CREATE TABLE idempotency_key (
  tenant_id       uuid NOT NULL,
  key             varchar(128) NOT NULL,
  request_hash    varchar(64) NOT NULL,
  response_status integer,
  response_body   jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, key)
);

-- Runtime access for the non-superuser application role (RLS does not apply to superusers).
DO $$
BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'meridian_app') THEN
    GRANT USAGE ON SCHEMA fraud TO meridian_app;
    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA fraud TO meridian_app;
    ALTER DEFAULT PRIVILEGES IN SCHEMA fraud GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO meridian_app;
  END IF;
END $$;
